import "./PreferenceDialog.scss"
import { PreferenceDialogViewModel } from "./PreferenceDialogViewModel"
import { consoleInfo } from "../../util/log"
import { BaseDialog, getDialogController, PREFERENCE_DIALOG_WRAPPER_ID, showDialog } from "./BaseDialog"
import type { BaseDialogOpenProps } from "./BaseDialog"
import { NewMdSwitch } from "../react/Switch"
import React, { useCallback, useEffect, useMemo, useRef, useSyncExternalStore } from "react"
import { createHtmlContent } from "../../util/tools"
import { EVENT_PAGE_BACK_FROM_CACHE, getEventEmitter, type Events } from "../base/EventBus"
import { LottieAnimation, type LottieAnimationController } from "../react/LottieAnimation"
import { setupRipple } from "../ripple"

export function PreferenceDialog(props: BaseDialogOpenProps) {
    const viewModel = useMemo(() => {
        return new PreferenceDialogViewModel()
    }, [])

    const state = useSyncExternalStore(viewModel.subscribe, () => viewModel.state)
    const animationControllerRef = useRef<LottieAnimationController | null>(null)

    useEffect(() => {
        consoleInfo("PreferenceDialogContent useEffect, subscribe to viewModel")
        const emitter = getEventEmitter()
        const pageEventListener = (pageEvent: Events["pageEvent"]) => {
            consoleInfo("PreferenceDialogContent receive event: " + pageEvent)
            // 订阅页面从缓存中恢复的事件，加载最新的设置状态
            if (props.dialogControllerRef?.current?.opened && pageEvent == EVENT_PAGE_BACK_FROM_CACHE) {
                viewModel.initSettings()
            }
        }
        emitter.on("pageEvent", pageEventListener)
        return () => {
            emitter.off("pageEvent", pageEventListener)
        }
    }, [viewModel, props.dialogControllerRef])

    const notoSerifSCFontTitle = useMemo(() => {
        return "使用<a href=\"https://source.typekit.com/source-han-serif/cn/\" target=\"_blank\" tabIndex=\"-1\">思源宋体</a>"
    }, [])

    const autoThemeTitle = useMemo(() => {
        return "自适应<a href=\"/post/original/2021/08/03/为博客添加站内搜索和深色模式.html\" tabIndex=\"-1\">深色模式</a>"
    }, [])

    const onDialogOpen = useCallback(() => {
        consoleInfo("PreferenceDialogContent onDialogOpen")
        viewModel.initSettings()
        animationControllerRef.current?.play()
    }, [viewModel])

    const onDialogClose = useCallback(() => {
        consoleInfo("PreferenceDialogContent onDialogClose")
        animationControllerRef.current?.pause()
    }, [])

    return (
        <BaseDialog dialogControllerRef={props.dialogControllerRef} onDialogOpen={onDialogOpen} onDialogClose={onDialogClose}>
            <div className="common-lottie-container">
                <LottieAnimation loop={true} autoplay={false} animationDataUrl={"https://apqx-host.oss-cn-hangzhou.aliyuncs.com/blog/emojis/noto-animated-emoji/mouth-none/lottie.json"}
                    animationControllerRef={animationControllerRef} />
            </div>
            <ul className="mdm-list mdm-list-no-hover" id="preference-dialog__toggle-container">
                <SettingsToggle titleHtml="固定顶部导航栏" description="滚动时导航栏固定显示在顶部"
                    on={state.fixedTopbar}
                    onChange={viewModel.onClickFixedTopbarSwitch} />
                <SettingsToggle titleHtml="隐藏状态栏背景" description="边到边模式下隐藏顶部状态栏背景"
                    on={state.hideStatusBarBg}
                    onChange={viewModel.onClickHideStatusBarBgSwitch} />
                <SettingsToggle titleHtml={"透镜显示更大图像"} description="减少小屏幕下透镜分区的分栏数"
                    on={state.lensBiggerPicture}
                    onChange={viewModel.onClickLensBiggerPictureSwitch} />
                <SettingsToggle titleHtml={notoSerifSCFontTitle} description="全局字体从默认黑体改为衬线宋体"
                    on={state.notoSerifSCFont}
                    onChange={viewModel.onClickNotoSerifSCFontSwitch} />
                <SettingsToggle titleHtml={autoThemeTitle} description="跟随系统设置自动切换明暗主题色"
                    on={state.autoTheme}
                    onChange={viewModel.onClickAutoThemeSwitch} />
                <SettingsToggle titleHtml={"展现更具表现力的色彩与设计"} description="实验性支持 Material 3 Expressive"
                    on={state.themeExpressive}
                    onChange={viewModel.onClickThemeExpressiveSwitch} />
            </ul>
        </BaseDialog>
    )
}

interface SettingsToggleProps {
    titleHtml: string
    description?: string
    on: boolean
    onChange: (event: Event) => void
}

export function SettingsToggle(props: SettingsToggleProps) {
    const containerRef = React.useRef<HTMLLIElement>(null)

    useEffect(() => {
        const rootE = containerRef.current as HTMLElement;
        const liE = rootE.querySelector(".mdm-list-item") as HTMLElement
        setupRipple(liE)
    }, [])

    return (
        <li ref={containerRef}>
            <div className="mdm-list-item mdm-list-item-darken preference-item-toggle">
                <div className="mdm-list-item__text">
                    <div className="mdm-list-item__primary-text"
                        dangerouslySetInnerHTML={createHtmlContent(props.titleHtml)} />
                    {
                        props.description &&
                        <div className="mdm-list-item__secondary-text">
                            {props.description}
                        </div>
                    }
                </div>
                {/* 会自动识别组建内定义的属性 */}
                <NewMdSwitch icons selected={props.on} onChange={props.onChange} />
            </div>
        </li>
    )
}

export function showPreferenceDialog() {
    consoleInfo("PreferenceDialogContent showPreferenceDialog")
    const id = PREFERENCE_DIALOG_WRAPPER_ID
    const dialogControllerRef = getDialogController(id)
    showDialog(<PreferenceDialog dialogControllerRef={dialogControllerRef} />, id)
    if (dialogControllerRef.current) {
        dialogControllerRef.current.open()
    }
}
